'use strict';

var defineProperty = require( '@stdlib/utils/define-property' );
var SplitSymbol = require( './../lib' );

// Define a custom split function that reverses the order
function reverseSplit( str ) {
	var result = str.split( /-/ );
	return result.reverse();
}

// Create a regular expression
var regexp = /-/;

// Set the custom split function
defineProperty( regexp, SplitSymbol, {
	'configurable': true,
	'writable': true,
	'value': reverseSplit
});

// Use the custom split
var str = 'a-b-c';
var result = str.split( regexp );
console.log( result );
// => ['c', 'b', 'a']
